<?php
declare(strict_types=1);
require dirname(__DIR__, 2) . '/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\DanceCupScoringService;
Auth::requireAdmin();$test=(string)($_GET['data_mode']??$_POST['data_mode']??'')==='test';if($test&&!Auth::isSuperAdmin()){http_response_code(403);exit('Super Admin required.');}$id=(int)($_GET['id']??$_POST['id']??0);$pdo=Database::connection();$tables=DanceCupScoringService::tables($test);$prefix=$test?'bdc_test_dance_cup':'bdc_dance_cup';$query=$pdo->prepare("SELECT c.*,e.name event_name,e.status event_status FROM {$tables['competitions']} c JOIN {$tables['events']} e ON e.id=c.event_id WHERE c.id=:id");$query->execute(['id'=>$id]);$category=$query->fetch();if(!$category){http_response_code(404);exit('Dance Cup category not found.');}$workflow=in_array((string)$category['scoring_mode'],['manual','automatic'],true)?(string)$category['scoring_mode']:'manual';$suffix=$test?'&data_mode=test':'';$error='';if((string)$category['status']!=='draft'){http_response_code(409);exit('Submitted scoring cannot be deleted. Return to the dashboard to open the locked results.');}
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');if((string)($_POST['confirmation']??'')!=='DELETE')throw new RuntimeException('Type DELETE exactly to confirm.');$pdo->beginTransaction();$lock=$pdo->prepare("SELECT c.status,e.status event_status FROM {$tables['competitions']} c JOIN {$tables['events']} e ON e.id=c.event_id WHERE c.id=:id FOR UPDATE");$lock->execute(['id'=>$id]);$locked=$lock->fetch();if(!$locked||(string)$locked['status']!=='draft')throw new RuntimeException('Submitted scoring cannot be deleted.');foreach(["{$prefix}_marks","{$prefix}_scoring_results","{$prefix}_judge_sessions","{$prefix}_checkpoints","{$prefix}_projection","{$prefix}_entries","{$prefix}_judges"] as $table)$pdo->prepare("DELETE FROM {$table} WHERE competition_id=:id")->execute(['id'=>$id]);$pdo->prepare("DELETE FROM {$prefix}_event_projection WHERE active_competition_id=:id")->execute(['id'=>$id]);$pdo->prepare("DELETE FROM {$tables['criteria']} WHERE competition_id=:id")->execute(['id'=>$id]);$deleteCompetition=$pdo->prepare("DELETE FROM {$tables['competitions']} WHERE id=:id AND status='draft'");$deleteCompetition->execute(['id'=>$id]);if($deleteCompetition->rowCount()!==1)throw new RuntimeException('Submitted scoring cannot be deleted.');$remaining=$pdo->prepare("SELECT COUNT(*) FROM {$tables['competitions']} WHERE event_id=:event");$remaining->execute(['event'=>(int)$category['event_id']]);if((int)$remaining->fetchColumn()===0&&(string)$locked['event_status']==='draft')$pdo->prepare("DELETE FROM {$tables['events']} WHERE id=:event AND status='draft'")->execute(['event'=>(int)$category['event_id']]);$pdo->commit();header('Location: workflow.php?workflow='.rawurlencode($workflow).$suffix.'&deleted=1',true,303);exit;}catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();$error=$exception->getMessage();}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Delete Dance Cup Draft</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:720px"><section class="card border-danger shadow-sm"><div class="card-body p-4"><span class="badge text-bg-danger">PROTECTED DELETE</span><h1 class="h4 mt-3">Delete this Draft category?</h1><p><strong><?=e($category['category_name'])?></strong><br><span class="text-muted"><?=e($category['event_name'])?> · <?=e(ucfirst($workflow))?> Scoring</span></p><div class="alert alert-warning">This permanently removes only this Draft category, its contestants, judges, links, marks, results and checkpoints. A submitted category cannot be deleted. An empty Draft parent event is also removed.</div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="data_mode" value="<?=$test?'test':'real'?>"><label class="form-label">Type <strong>DELETE</strong> to confirm</label><input class="form-control mb-3" name="confirmation" autocomplete="off" required><div class="d-flex gap-2"><button class="btn btn-danger">Delete Draft</button><a class="btn btn-outline-secondary" href="workflow.php?workflow=<?=e($workflow)?><?=$suffix?>">Cancel</a></div></form></div></section></main></body></html>
